def with_effects(candidates: list) -> list:
    """Item candidates with each one's `effect` added (unknown ids, a modded item, are left as they are)."""
    out = []
    for c in candidates:
        if isinstance(c, dict) and "effect" not in c:
            try:
                effect = ITEM_EFFECTS.get(int(c.get("id")))
            except (TypeError, ValueError):
                effect = None
            if effect:
                c = {**c, "effect": effect}
        out.append(c)
    return out
